export const GRAMMAR_ITFR = [{"id":"g_it_are","lang":"it","title":{"en":"Present tense: verbs in -are","de":"Präsens: Verben auf -are","es":"Presente: verbos en -are","ne":"वर्तमान काल: -are मा अन्त्य हुने क्रिया"},"rule":{"en":"parlare → parl- + -o, -i, -a, -iamo, -ate, -ano. The subject pronoun is usually dropped: Parlo italiano. Verbs in -iare keep only one i: studiare → tu studi.","de":"parlare → parl- + -o, -i, -a, -iamo, -ate, -ano. Das Subjektpronomen fällt meist weg: Parlo italiano. Bei Verben auf -iare bleibt nur ein i: studiare → tu studi.","es":"parlare → parl- + -o, -i, -a, -iamo, -ate, -ano. El pronombre sujeto se suele omitir: Parlo italiano. En los verbos en -iare queda una sola i: studiare → tu studi.","ne":"parlare → parl- + -o, -i, -a, -iamo, -ate, -ano। कर्ता सर्वनाम प्रायः छोडिन्छ: Parlo italiano। -iare मा अन्त्य हुने क्रियामा एउटा मात्र i रहन्छ: studiare → tu studi।"},"quiz":"conj","table":[["","parlare","lavorare","studiare"],["io","parlo","lavoro","studio"],["tu","parli","lavori","studi"],["lui/lei/Lei","parla","lavora","studia"],["noi","parliamo","lavoriamo","studiamo"],["voi","parlate","lavorate","studiate"],["loro","parlano","lavorano","studiano"]]},{"id":"g_it_essere","lang":"it","title":{"en":"essere and avere (to be, to have)","de":"essere und avere (sein, haben)","es":"essere y avere (ser/estar, tener)","ne":"essere र avere (हुनु, सँग हुनु)"},"rule":{"en":"The two most important verbs are irregular – learn them by heart. loro (they): sono, hanno – io sono and loro sono look the same. The h in ho, hai, ha, hanno is silent. Formal 'you' (Lei) uses the third person: Lei è, Lei ha.","de":"Die zwei wichtigsten Verben sind unregelmäßig – lerne sie auswendig. loro (sie, Plural): sono, hanno – io sono und loro sono sehen gleich aus. Das h in ho, hai, ha, hanno wird nicht gesprochen. Die Höflichkeitsform Lei steht in der 3. Person: Lei è, Lei ha.","es":"Los dos verbos más importantes son irregulares: apréndelos de memoria. loro (ellos): sono, hanno; io sono y loro sono coinciden. La h de ho, hai, ha, hanno no se pronuncia. La forma de cortesía Lei va en tercera persona: Lei è, Lei ha.","ne":"यी दुई सबैभन्दा महत्त्वपूर्ण क्रिया अनियमित छन् – कण्ठ गर्नुहोस्। loro (उनीहरू): sono, hanno – io sono र loro sono एउटै देखिन्छन्। ho, hai, ha, hanno मा h उच्चारण हुँदैन। आदरार्थी Lei तृतीय पुरुषमा आउँछ: Lei è, Lei ha।"},"quiz":"conj","table":[["","essere","avere"],["io","sono","ho"],["tu","sei","hai"],["lui/lei/Lei","è","ha"],["noi","siamo","abbiamo"],["voi","siete","avete"]]},{"id":"g_it_ere","lang":"it","title":{"en":"Verbs in -ere and -ire","de":"Verben auf -ere und -ire","es":"Verbos en -ere e -ire","ne":"-ere र -ire मा अन्त्य हुने क्रिया"},"rule":{"en":"-ere: -o, -i, -e, -iamo, -ete, -ono (prendere → prendo, prendete). -ire: the same, but voi ends in -ite (dormire → dormite). Many -ire verbs add -isc-: finire → finisco, finisci.","de":"-ere: -o, -i, -e, -iamo, -ete, -ono (prendere → prendo, prendete). -ire: gleich, aber voi endet auf -ite (dormire → dormite). Viele Verben auf -ire schieben -isc- ein: finire → finisco, finisci.","es":"-ere: -o, -i, -e, -iamo, -ete, -ono (prendere → prendo, prendete). -ire: igual, pero voi termina en -ite (dormire → dormite). Muchos verbos en -ire añaden -isc-: finire → finisco, finisci.","ne":"-ere: -o, -i, -e, -iamo, -ete, -ono (prendere → prendo, prendete)। -ire: उस्तै, तर voi मा -ite हुन्छ (dormire → dormite)। धेरै -ire क्रियामा -isc- थपिन्छ: finire → finisco, finisci।"},"quiz":"conj","table":[["","prendere","scrivere","dormire","partire"],["io","prendo","scrivo","dormo","parto"],["tu","prendi","scrivi","dormi","parti"],["lui/lei/Lei","prende","scrive","dorme","parte"],["noi","prendiamo","scriviamo","dormiamo","partiamo"],["voi","prendete","scrivete","dormite","partite"],["loro","prendono","scrivono","dormono","partono"]]},{"id":"g_it_art","lang":"it","title":{"en":"il, la or lo (gender)","de":"il, la oder lo","es":"il, la o lo (género)","ne":"il, la वा lo (लिङ्ग)"},"rule":{"en":"Masculine nouns take il (il libro), but lo before s + consonant, z, gn and ps (lo studente, lo zaino). Feminine nouns take la (la casa). Before a vowel, lo and la become l': l'amico, l'acqua.","de":"Maskuline Nomen haben il (il libro), aber lo vor s + Konsonant, z, gn und ps (lo studente, lo zaino). Feminine Nomen haben la (la casa). Vor Vokal werden lo und la zu l': l'amico, l'acqua.","es":"Los sustantivos masculinos llevan il (il libro), pero lo delante de s + consonante, z, gn y ps (lo studente, lo zaino). Los femeninos llevan la (la casa). Delante de vocal, lo y la se convierten en l': l'amico, l'acqua.","ne":"पुलिङ्ग नाममा il लाग्छ (il libro), तर s + व्यञ्जन, z, gn र ps अघि lo लाग्छ (lo studente, lo zaino)। स्त्रीलिङ्ग नाममा la लाग्छ (la casa)। स्वर अघि lo र la, l' बन्छन्: l'amico, l'acqua।"},"quiz":"article","articles":["il","la","lo"]},{"id":"g_fr_er","lang":"fr","title":{"en":"Present tense: verbs in -er","de":"Präsens: Verben auf -er","es":"Presente: verbos en -er","ne":"वर्तमान काल: -er मा अन्त्य हुने क्रिया"},"rule":{"en":"parler → parl- + -e, -es, -e, -ons, -ez, -ent. je and il/elle have the same form (je parle, il parle), and the endings -e, -es, -ent are silent. Before a vowel je becomes j': j'aime.","de":"parler → parl- + -e, -es, -e, -ons, -ez, -ent. je und il/elle haben dieselbe Form (je parle, il parle); die Endungen -e, -es, -ent spricht man nicht aus. Vor Vokal wird je zu j': j'aime.","es":"parler → parl- + -e, -es, -e, -ons, -ez, -ent. je e il/elle tienen la misma forma (je parle, il parle) y las terminaciones -e, -es, -ent no se pronuncian. Delante de vocal je se convierte en j': j'aime.","ne":"parler → parl- + -e, -es, -e, -ons, -ez, -ent। je र il/elle को रूप एउटै हुन्छ (je parle, il parle), र -e, -es, -ent प्रत्यय उच्चारण हुँदैनन्। स्वर अघि je, j' बन्छ: j'aime।"},"quiz":"conj","table":[["","parler","travailler","chanter"],["je, il/elle","parle","travaille","chante"],["tu","parles","travailles","chantes"],["nous","parlons","travaillons","chantons"],["vous","parlez","travaillez","chantez"],["ils/elles","parlent","travaillent","chantent"]]},{"id":"g_fr_etre","lang":"fr","title":{"en":"être and avoir (to be, to have)","de":"être und avoir (sein, haben)","es":"être y avoir (ser/estar, tener)","ne":"être र avoir (हुनु, सँग हुनु)"},"rule":{"en":"The two most important verbs are irregular – learn them by heart. Before a vowel je becomes j': je suis, but j'ai. vous is also the polite form: vous êtes, vous avez.","de":"Die zwei wichtigsten Verben sind unregelmäßig – lerne sie auswendig. Vor Vokal wird je zu j': je suis, aber j'ai. vous ist auch die Höflichkeitsform: vous êtes, vous avez.","es":"Los dos verbos más importantes son irregulares: apréndelos de memoria. Delante de vocal je se convierte en j': je suis, pero j'ai. vous es también la forma de cortesía: vous êtes, vous avez.","ne":"यी दुई सबैभन्दा महत्त्वपूर्ण क्रिया अनियमित छन् – कण्ठ गर्नुहोस्। स्वर अघि je, j' बन्छ: je suis, तर j'ai। vous आदरार्थी रूप पनि हो: vous êtes, vous avez।"},"quiz":"conj","table":[["","être","avoir"],["je/j'","suis","ai"],["tu","es","as"],["il/elle","est","a"],["nous","sommes","avons"],["vous","êtes","avez"],["ils/elles","sont","ont"]]},{"id":"g_fr_pc","lang":"fr","title":{"en":"Passé composé: past participles","de":"Passé composé: Partizip Perfekt","es":"Passé composé: participios","ne":"Passé composé: भूत कृदन्त"},"rule":{"en":"Passé composé = avoir (or être) in the present + past participle: j'ai mangé, elle est venue. -er → -é (parler → parlé), -ir → -i (finir → fini). Many common verbs are irregular: faire → fait, prendre → pris, voir → vu.","de":"Passé composé = avoir (oder être) im Präsens + Partizip: j'ai mangé, elle est venue. -er → -é (parler → parlé), -ir → -i (finir → fini). Viele häufige Verben sind unregelmäßig: faire → fait, prendre → pris, voir → vu.","es":"Passé composé = avoir (o être) en presente + participio: j'ai mangé, elle est venue. -er → -é (parler → parlé), -ir → -i (finir → fini). Muchos verbos frecuentes son irregulares: faire → fait, prendre → pris, voir → vu.","ne":"Passé composé = वर्तमान कालको avoir (वा être) + भूत कृदन्त: j'ai mangé, elle est venue। -er → -é (parler → parlé), -ir → -i (finir → fini)। धेरै प्रचलित क्रिया अनियमित छन्: faire → fait, prendre → pris, voir → vu।"},"quiz":"pairs","table":[["verbe","passé composé","",""],["parler","parlé","parlu","parli"],["aller","allé","allu","alli"],["finir","fini","finé","finu"],["faire","fait","fairé","faisé"],["prendre","pris","prendu","prené"],["mettre","mis","mettu","metté"],["dire","dit","disé","diru"],["écrire","écrit","écriru","écrivé"],["voir","vu","voyé","voiru"],["boire","bu","boiré","buvé"],["lire","lu","lisé","liré"],["venir","venu","viendu","venié"],["ouvrir","ouvert","ouvri","ouvré"],["pouvoir","pu","pouvu","pouvé"],["avoir","eu","avé","avu"],["être","été","étu","êtré"]]},{"id":"g_fr_art","lang":"fr","title":{"en":"le or la (gender)","de":"le oder la","es":"le o la (género)","ne":"le वा la (लिङ्ग)"},"rule":{"en":"Nouns are masculine (le) or feminine (la): le livre, la maison. Before a vowel or a silent h both become l': l'ami, l'eau, l'hôtel. Words in -tion are usually feminine; words in -ment and -age are usually masculine.","de":"Nomen sind maskulin (le) oder feminin (la): le livre, la maison. Vor Vokal oder stummem h werden beide zu l': l'ami, l'eau, l'hôtel. Wörter auf -tion sind meist feminin, Wörter auf -ment und -age meist maskulin.","es":"Los sustantivos son masculinos (le) o femeninos (la): le livre, la maison. Delante de vocal o h muda ambos se convierten en l': l'ami, l'eau, l'hôtel. Las palabras en -tion suelen ser femeninas; las terminadas en -ment y -age, masculinas.","ne":"नाम पुलिङ्ग (le) वा स्त्रीलिङ्ग (la) हुन्छन्: le livre, la maison। स्वर वा मौन h अघि दुवै l' बन्छन्: l'ami, l'eau, l'hôtel। -tion मा अन्त्य हुने शब्द प्रायः स्त्रीलिङ्ग र -ment, -age मा अन्त्य हुने शब्द प्रायः पुलिङ्ग हुन्छन्।"},"quiz":"article","articles":["le","la"]}];

// Grammar topic titles and rules for the Italian and French interface: id → {it:{title, rule}, fr:{title, rule}}.
export const GRAMMAR_UI_ITFR = {"g_de_sein":{"it":{"title":"sein e haben (essere, avere)","rule":"I due verbi più importanti sono irregolari – imparali a memoria. La forma di cortesia (Sie) usa la stessa forma di 'loro' (sie)."},"fr":{"title":"sein et haben (être, avoir)","rule":"Ce sont les deux verbes les plus importants, et ils sont irréguliers – apprends-les par cœur. Le « vous » de politesse (Sie) a la même forme que « ils/elles » (sie)."}},"g_de_present":{"it":{"title":"Presente: verbi regolari","rule":"Radice + desinenza: ich -e, du -st, er/sie/es -t, wir -en, ihr -t, sie/Sie -en. lernen → ich lerne, du lernst."},"fr":{"title":"Présent : verbes réguliers","rule":"Radical + terminaison : ich -e, du -st, er/sie/es -t, wir -en, ihr -t, sie/Sie -en. lernen → ich lerne, du lernst."}},"g_de_vowel":{"it":{"title":"Verbi con cambio vocalico","rule":"Alcuni verbi cambiano la vocale solo con du ed er/sie/es: essen → du isst, fahren → du fährst."},"fr":{"title":"Verbes à changement de voyelle","rule":"Certains verbes changent de voyelle seulement avec du et er/sie/es : essen → du isst, fahren → du fährst."}},"g_de_art":{"it":{"title":"der, die, das (genere)","rule":"Ogni sostantivo ha un genere: der (maschile), die (femminile), das (neutro). Impara sempre un sostantivo con il suo articolo."},"fr":{"title":"der, die, das (genre)","rule":"Chaque nom a un genre : der (masculin), die (féminin), das (neutre). Apprends toujours un nom avec son article."}},"g_es_ser":{"it":{"title":"ser ed estar (essere)","rule":"ser: chi o che cosa è qualcosa (origine, professione, natura). estar: dove si trova qualcosa e come sta qualcuno in questo momento."},"fr":{"title":"ser et estar (être)","rule":"ser : qui ou ce qu'est quelque chose (origine, métier, nature). estar : où se trouve quelque chose et comment va quelqu'un en ce moment."}},"g_es_ar":{"it":{"title":"Verbi in -ar","rule":"hablar → habl- + -o, -as, -a, -amos, -áis, -an. Il pronome soggetto spesso si omette: Hablo español."},"fr":{"title":"Verbes en -ar","rule":"hablar → habl- + -o, -as, -a, -amos, -áis, -an. Le pronom sujet est souvent omis : Hablo español."}},"g_es_er":{"it":{"title":"Verbi in -er e -ir","rule":"-er: -o, -es, -e, -emos, -éis, -en (comer). -ir: uguali, ma -imos, -ís (vivir → vivimos)."},"fr":{"title":"Verbes en -er et -ir","rule":"-er : -o, -es, -e, -emos, -éis, -en (comer). -ir : pareil, mais -imos, -ís (vivir → vivimos)."}},"g_es_art":{"it":{"title":"el o la (genere)","rule":"I sostantivi sono maschili (el) o femminili (la). Spesso -o è maschile e -a femminile – ma el día, la mano, el agua."},"fr":{"title":"el ou la (genre)","rule":"Les noms sont masculins (el) ou féminins (la). Souvent, -o est masculin et -a féminin – mais el día, la mano, el agua."}},"g_en_be":{"it":{"title":"to be e to have (essere, avere)","rule":"I am, you are, he/she/it is, we/they are. To have: I/you/we/they have, he/she/it has."},"fr":{"title":"to be et to have","rule":"I am, you are, he/she/it is, we/they are. To have : I/you/we/they have, he/she/it has."}},"g_en_present":{"it":{"title":"Present simple: -s con he/she/it","rule":"Solo he/she/it aggiunge -s: I work, she works. Dopo -ch, -sh, -o: -es (watches, goes). Consonante + y → -ies (studies)."},"fr":{"title":"Present simple : -s avec he/she/it","rule":"Seuls he/she/it prennent un -s : I work, she works. Après -ch, -sh, -o : -es (watches, goes). Consonne + y → -ies (studies)."}},"g_en_past":{"it":{"title":"Past simple irregolare","rule":"I verbi regolari aggiungono -ed (worked). Molti verbi comuni sono irregolari – imparali a coppie: go → went."},"fr":{"title":"Past simple irrégulier","rule":"Les verbes réguliers prennent -ed (worked). Beaucoup de verbes courants sont irréguliers – apprends-les par paires : go → went."}},"g_ne_hunu":{"it":{"title":"हुनु – essere (हो)","rule":"Per l'identità: म … हुँ, तिमी … हौ, ऊ … हो, हामी … हौं, तपाईं … हुनुहुन्छ (cortese)."},"fr":{"title":"हुनु – être (हो)","rule":"Pour l'identité : म … हुँ, तिमी … हौ, ऊ … हो, हामी … हौं, तपाईं … हुनुहुन्छ (poli)."}},"g_ne_present":{"it":{"title":"Presente (abituale)","rule":"Radice del verbo + desinenza: म -छु, तिमी -छौ, ऊ -छ, हामी -छौं, तपाईं -नुहुन्छ. गर्नु → म गर्छु."},"fr":{"title":"Présent (habituel)","rule":"Radical du verbe + terminaison : म -छु, तिमी -छौ, ऊ -छ, हामी -छौं, तपाईं -नुहुन्छ. गर्नु → म गर्छु."}},"g_ko_yo":{"it":{"title":"Presente cortese -아요/-어요","rule":"Radice con ㅏ/ㅗ → -아요 (가다 → 가요), altrimenti -어요 (먹다 → 먹어요), 하다 → 해요."},"fr":{"title":"Présent poli -아요/-어요","rule":"Radical avec ㅏ/ㅗ → -아요 (가다 → 가요), sinon -어요 (먹다 → 먹어요), 하다 → 해요."}},"g_ko_cop":{"it":{"title":"이에요 / 예요 (essere)","rule":"Dopo una consonante finale (batchim) usa -이에요, dopo una vocale -예요: 책이에요, 의자예요."},"fr":{"title":"이에요 / 예요 (être)","rule":"Après une consonne finale (batchim), utilise -이에요, après une voyelle -예요 : 책이에요, 의자예요."}},"g_ko_part":{"it":{"title":"Particelle 은/는, 이/가, 을/를","rule":"Tema 은/는, soggetto 이/가, oggetto 을/를. Usa la prima forma dopo una consonante, la seconda dopo una vocale."},"fr":{"title":"Particules 은/는, 이/가, 을/를","rule":"Thème 은/는, sujet 이/가, objet 을/를. Utilise la première forme après une consonne, la seconde après une voyelle."}},"g_it_are":{"it":{"title":"Presente: verbi in -are","rule":"parlare → parl- + -o, -i, -a, -iamo, -ate, -ano. Il pronome soggetto di solito si omette: Parlo italiano. I verbi in -iare mantengono una sola i: studiare → tu studi."},"fr":{"title":"Présent : verbes en -are","rule":"parlare → parl- + -o, -i, -a, -iamo, -ate, -ano. Le pronom sujet est généralement omis : Parlo italiano. Les verbes en -iare ne gardent qu'un seul i : studiare → tu studi."}},"g_it_essere":{"it":{"title":"essere e avere","rule":"I due verbi più importanti sono irregolari – imparali a memoria. loro: sono, hanno – io sono e loro sono hanno la stessa forma. La h di ho, hai, ha, hanno non si pronuncia. La forma di cortesia (Lei) usa la terza persona: Lei è, Lei ha."},"fr":{"title":"essere et avere (être, avoir)","rule":"Ce sont les deux verbes les plus importants, et ils sont irréguliers – apprends-les par cœur. loro (ils/elles) : sono, hanno – io sono et loro sono ont la même forme. Le h de ho, hai, ha, hanno ne se prononce pas. Le « vous » de politesse (Lei) utilise la troisième personne : Lei è, Lei ha."}},"g_it_ere":{"it":{"title":"Verbi in -ere e -ire","rule":"-ere: -o, -i, -e, -iamo, -ete, -ono (prendere → prendo, prendete). -ire: uguali, ma voi finisce in -ite (dormire → dormite). Molti verbi in -ire aggiungono -isc-: finire → finisco, finisci."},"fr":{"title":"Verbes en -ere et -ire","rule":"-ere : -o, -i, -e, -iamo, -ete, -ono (prendere → prendo, prendete). -ire : pareil, mais voi se termine en -ite (dormire → dormite). Beaucoup de verbes en -ire ajoutent -isc- : finire → finisco, finisci."}},"g_it_art":{"it":{"title":"il, la o lo (genere)","rule":"I sostantivi maschili vogliono il (il libro), ma lo davanti a s + consonante, z, gn e ps (lo studente, lo zaino). I sostantivi femminili vogliono la (la casa). Davanti a vocale, lo e la diventano l': l'amico, l'acqua."},"fr":{"title":"il, la ou lo (genre)","rule":"Les noms masculins prennent il (il libro), mais lo devant s + consonne, z, gn et ps (lo studente, lo zaino). Les noms féminins prennent la (la casa). Devant une voyelle, lo et la deviennent l' : l'amico, l'acqua."}},"g_fr_er":{"it":{"title":"Presente: verbi in -er","rule":"parler → parl- + -e, -es, -e, -ons, -ez, -ent. je e il/elle hanno la stessa forma (je parle, il parle), e le desinenze -e, -es, -ent non si pronunciano. Davanti a vocale je diventa j': j'aime."},"fr":{"title":"Présent : verbes en -er","rule":"parler → parl- + -e, -es, -e, -ons, -ez, -ent. je et il/elle ont la même forme (je parle, il parle), et les terminaisons -e, -es, -ent ne se prononcent pas. Devant une voyelle, je devient j' : j'aime."}},"g_fr_etre":{"it":{"title":"être e avoir (essere, avere)","rule":"I due verbi più importanti sono irregolari – imparali a memoria. Davanti a vocale je diventa j': je suis, ma j'ai. vous è anche la forma di cortesia: vous êtes, vous avez."},"fr":{"title":"être et avoir","rule":"Ce sont les deux verbes les plus importants, et ils sont irréguliers – apprends-les par cœur. Devant une voyelle, je devient j' : je suis, mais j'ai. vous est aussi la forme de politesse : vous êtes, vous avez."}},"g_fr_pc":{"it":{"title":"Passé composé: participi passati","rule":"Passé composé = avoir (o être) al presente + participio passato: j'ai mangé, elle est venue. -er → -é (parler → parlé), -ir → -i (finir → fini). Molti verbi comuni sono irregolari: faire → fait, prendre → pris, voir → vu."},"fr":{"title":"Passé composé : participes passés","rule":"Passé composé = avoir (ou être) au présent + participe passé : j'ai mangé, elle est venue. -er → -é (parler → parlé), -ir → -i (finir → fini). Beaucoup de verbes courants sont irréguliers : faire → fait, prendre → pris, voir → vu."}},"g_fr_art":{"it":{"title":"le o la (genere)","rule":"I sostantivi sono maschili (le) o femminili (la): le livre, la maison. Davanti a vocale o h muta entrambi diventano l': l'ami, l'eau, l'hôtel. Le parole in -tion sono di solito femminili; quelle in -ment e -age di solito maschili."},"fr":{"title":"le ou la (genre)","rule":"Les noms sont masculins (le) ou féminins (la) : le livre, la maison. Devant une voyelle ou un h muet, les deux deviennent l' : l'ami, l'eau, l'hôtel. Les mots en -tion sont généralement féminins ; les mots en -ment et -age sont généralement masculins."}}};
